  "designer.js",
  "particular.js",
  "form.js",
  "plexus.js",
  "lights-c4d.js",
];

const TRAPCODE_TYPES = [
  { type: 10, key: "particular" },
  { type: 11, key: "form" },
  { type: 12, key: "plexus" },
